/**
 * setup.cjs - 在 Main 進程中設置 native module 路徑
 *
 * 使用方式（在 Electron main process 中）：
 *
 *   const mpvSetup = require('/path/to/mpv-video-player-prebuilt/setup.cjs');
 *   mpvSetup.setup();
 *
 * 或者手動取得路徑：
 *
 *   const mpvSetup = require('/path/to/mpv-video-player-prebuilt/setup.cjs');
 *   process.env.MPV_NATIVE_MODULE_PATH = mpvSetup.nativeModulePath;
 */

const path = require('path');

const pkgRoot = __dirname;
const nativeModulePath = path.join(
    pkgRoot, 'native', 'video-player', 'build', 'Release', 'video_player.node'
);

/**
 * native module (.node) 的完整路徑
 */
exports.nativeModulePath = nativeModulePath;

/**
 * runtime libraries 所在目錄（dylibs / DLLs）
 */
exports.nativeLibDir = path.join(
    pkgRoot, 'native', 'video-player', 'build', 'Release'
);

/**
 * 套件根目錄
 */
exports.packageRoot = pkgRoot;

/**
 * 預編譯資訊
 */
exports.prebuiltInfo = {
    "platform": "win32",
    "arch": "x64",
    "electronVersion": "22.3.7"
};

/**
 * 設置環境變量，讓 Renderer 進程能自動找到 native module
 *
 * 在 Electron main process 的最早期呼叫此函數。
 * 會設置 process.env.MPV_NATIVE_MODULE_PATH。
 */
exports.setup = function setup() {
    const fs = require('fs');
    if (!fs.existsSync(nativeModulePath)) {
        throw new Error(
            '[mpv-video-player] Native module not found at: ' + nativeModulePath + '\n' +
            'This pre-built package was compiled for ' +
            'win-x64 (Electron 22.3.7). ' +
            'Make sure the platform matches your environment.'
        );
    }
    process.env.MPV_NATIVE_MODULE_PATH = nativeModulePath;
    return nativeModulePath;
};
